private int inversionSort(int[] A, int low, int high) {
    if (low == high) return 0;
    int invCount = 0;
    int mid = (low + high) / 2;
    invCount = (invCount + inversionSort(A, low, mid)) % 1_000_000_007;
    invCount = (invCount + inversionSort(A, mid + 1, high)) % 1_000_000_007;
    invCount = (invCount + inversionMerge(A, low, mid, high)) % 1_000_000_007;
    return invCount;
}

private int inversionMerge(int[] A, int low, int mid, int high) {
    int P1 = low;
    int P2 = mid + 1;
    int index = 0;
    int invCount = 0;
    int[] temp = new int[high - low + 1];
    while (P1 < mid + 1 && P2 < high + 1) {
        if (A[P1] <= A[P2]) {
            temp[index] = A[P1];
            P1++;
        } else {
            invCount = (invCount + (mid + 1 - P1)) % 1_000_000_007;
            temp[index] = A[P2];
            P2++;
        }
        index++;
    }
    while (P1 < mid + 1) { temp[index++] = A[P1++]; }
    while (P2 < high + 1) { temp[index++] = A[P2++]; }
    for (int i = 0; i < temp.length; i++) A[low + i] = temp[i];
    return invCount;
}

