public int[] solve(int[] A) {
    int n = A.length;
    // Find maximum value
    int max = 0;
    for (int x : A) {
        if (x > max) {
            max = x;
        }
    }
    // Count frequency
    int[] count = new int[max + 1];
    for (int x : A) {
        count[x]++;
    }
    // Build sorted array
    int[] result = new int[n];
    int index = 0;
    for (int i = 0; i <= max; i++) {
        while (count[i] > 0) {
            result[index++] = i;
            count[i]--;
        }
    }
    return result;
}

public int[] sortSubarray(int[] A, int B, int C) {
    // Extract subarray
    int[] temp = new int[C - B + 1];
    for (int i = B; i <= C; i++) {
        temp[i - B] = A[i];
    }
    // Sort the subarray
    Arrays.sort(temp);
    // Put back sorted elements
    for (int i = B; i <= C; i++) {
        A[i] = temp[i - B];
    }
    return A;
}

