private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

public void quickSort(int[] A, int start, int end) {
    if (start >= end) {
        return;
    }
    int index = pivotPartition(A, start, end);
    quickSort(A, start, index - 1);
    quickSort(A, index + 1, end);
}

public int pivotPartition(int[] A, int first, int last) {
    int pivot = A[first];
    int left = first + 1;
    int right = last;
    while (left <= right) {
        if (A[left] <= pivot) {
            left++;
        } else if (A[right] > pivot) {
            right--;
        } else {
            swap(A, left, right);
        }
    }
    swap(A, first, right);
    return right;
}

public int partition(int[] A) {
    int n = A.length;
    int pivot = A[n - 1];
    int i = 0;                    // boundary: A[0..i-1] < pivot
    for (int j = 0; j < n - 1; j++) {
        if (A[j] < pivot) {
            swap(A, i, j);
            i++;
        }
    }
    swap(A, i, n - 1);            // seat the pivot
    return i;                     // partition index
}

private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

