public static int[] waveSort(int[] A) {
    Arrays.sort(A); // Step 1: sort for lexicographic minimality
    // Step 2: swap each adjacent pair (peaks at even indices)
    for (int i = 0; i < A.length - 1; i += 2) {
        int temp = A[i];
        A[i] = A[i + 1];
        A[i + 1] = temp;
    }
    return A;
}

