public int[] solve(int[] A) {
    Integer[] B = new Integer[A.length];
    for (int i = 0; i < A.length; i++) B[i] = A[i];
    Arrays.sort(B, (x, y) -> {
        int tx = (x / 10) % 10;
        int ty = (y / 10) % 10;
        if (tx != ty) return tx - ty;   // tens digit ascending
        return y - x;                    // same tens: larger value first
    });
    int[] res = new int[A.length];
    for (int i = 0; i < A.length; i++) res[i] = B[i];
    return res;
}

public int[] sort01(int[] A) {
    int left = 0, right = A.length - 1;
    while (left < right) {
        if (A[left] == 0) {
            left++;
        } else if (A[right] == 1) {
            right--;
        } else {
            A[left] = 0;
            A[right] = 1;
            left++;
            right--;
        }
    }
    return A;
}
